pub assume_specification<'a, T, A: Allocator, B: Ord, F: FnMut(&'a T) -> B>[
    VecDeque::<T, A>::binary_search_by_key
](
    v: &'a VecDeque<T, A>,
    b: &B,
    f: F,
) -> (result: Result<usize, usize>)
    requires
        B::obeys_cmp_spec(),
        forall|i: int| 0 <= i < v@.len() ==> {
            &&& #[trigger] f.requires((v@.as_ref()[i],))
            &&& exists|key: B| #[trigger] f.ensures((v@.as_ref()[i],), key)
        },
        forall|i: int, j: int, key_i: B, key_j: B|
            0 <= i <= j < v@.len()
            && f.ensures((v@.as_ref()[i],), key_i)
            && f.ensures((v@.as_ref()[j],), key_j) ==>
                key_i.cmp_spec(b) == Ordering::Less
                || key_j.cmp_spec(b) == Ordering::Greater
                || key_i.cmp_spec(b) == key_j.cmp_spec(b),
    ensures
        match result {
            Ok(i) => {
                &&& (i as int) < v@.len()
                &&& exists|key: B| {
                    &&& f.ensures((v@.as_ref()[i as int],), key)
                    &&& key.cmp_spec(b) == Ordering::Equal
                }
            },
            Err(i) => {
                &&& (i as int) <= v@.len()
                &&& forall|j: int, key: B|
                    0 <= j < v@.len()
                    && f.ensures((v@.as_ref()[j],), key) ==> {
                        &&& (j < i as int ==> key.cmp_spec(b) == Ordering::Less)
                        &&& (i as int <= j ==> key.cmp_spec(b) == Ordering::Greater)
                    }
            },
        },
;

pub assume_specification<T, A: Allocator>[
    VecDeque::<T, A>::pop_back_if
](
    v: &mut VecDeque<T, A>,
    predicate: impl FnOnce(&mut T) -> bool,
) -> (result: Option<T>)
    requires
        old(v)@.len() > 0 ==> forall|x: &mut T| #![auto]
            *x == old(v)@[old(v)@.len() as int - 1] ==> predicate.requires((x,)),
    ensures
        old(v)@.len() == 0 ==> result is None && final(v)@ == old(v)@,
        old(v)@.len() > 0 ==> exists|x: &mut T, take: bool| #![auto] {
            &&& *x == old(v)@[old(v)@.len() as int - 1]
            &&& predicate.ensures((x,), take)
            &&& (take ==> {
                &&& result == Some(*final(x))
                &&& final(v)@ == old(v)@.subrange(0, old(v)@.len() as int - 1)
            })
            &&& (!take ==> {
                &&& result is None
                &&& final(v)@ == old(v)@.update(old(v)@.len() as int - 1, *final(x))
            })
        },
;

ensures:
old(v)@.len() == 0 ==> result is None && final(v)@ == old(v)@; old(v)@.len() > 0 ==> exists|x: &mut T, take: bool| {
            &&& *x == old(v)@[0]
            &&& predicate.ensures((x,), take)
            &&& (take ==> {
                &&& result == Some(*final(x))
                &&& final(v)@ == old(v)@.subrange(1, old(v)@.len() as int)
            })
            &&& (!take ==> {
                &&& result is None
                &&& final(v)@ == old(v)@.update(0, *final(x))
            })
        }

