pub assume_specification<T, P>[
    Option::<T>::take_if
](
    option: &mut Option<T>,
    predicate: P,
) -> (result: Option<T>)
where
    P: FnOnce(&mut T) -> bool,
    requires
        *old(option) is Some ==> forall |arg: &mut T| #![auto]
            *arg == old(option)->0 ==> predicate.requires((arg,)),
    ensures
        *old(option) is None ==> result is None && *final(option) is None,
        *old(option) is Some ==> exists |arg: &mut T, take: bool| #![auto] {
            &&& *arg == old(option)->0
            &&& predicate.ensures((arg,), take)
            &&& if take {
                result == Some(*final(arg)) && *final(option) is None
            } else {
                result is None && *final(option) == Some(*final(arg))
            }
        },
;

ensures:
match result {
    Result::Ok(index) => {
        &&& (index as int) < slice@.len()
        &&& f.ensures((&slice@[index as int],), Ordering::Equal)
        &&& forall|i: int| #![auto]
            i > index as int && slice@.len() > i ==>
                f.ensures((&slice@[i],), Ordering::Greater)
    },
    Result::Err(index) => {
        &&& (index as int) <= slice@.len()
        &&& forall|i: int| #![auto]
            i >= 0 && index as int > i ==>
                f.ensures((&slice@[i],), Ordering::Less)
        &&& forall|i: int| #![auto]
            i >= index as int && slice@.len() > i ==>
                f.ensures((&slice@[i],), Ordering::Greater)
    },
}

contract_code:
pub assume_specification<'a, T, B: core::cmp::Ord, F: FnMut(&'a T) -> B>[ <[T]>::binary_search_by_key ](
    slice: &'a [T],
    b: &B,
    f: F,
) -> (result: Result<usize, usize>)
    requires
        forall|i: int| 0 <= i < slice@.len() ==> f.requires((&slice@[i],)),
    ensures
        slice.len() == 0 ==> result == Result::<usize, usize>::Err(0),
        result is Ok ==> {
            &&& result->Ok_0 < slice.len()
            &&& exists|key: B| {
                &&& f.ensures((&slice@[result->Ok_0 as int],), key)
                &&& call_ensures(
                    <B as core::cmp::Ord>::cmp,
                    (&key, b),
                    Ordering::Equal,
                )
            }
        },
        result is Err ==> result->Err_0 <= slice.len(),
;
